 static JSONObject action(String kind,JSONObject p)throws Exception{return OffersAndPhotosTests.event("request-"+kind,kind,p);}
 static JSONObject expected(JSONObject p)throws Exception{return new JSONObject().put("id",p.getString("id")).put("expected_record_hash",PixelMcpWriteTools.hash(DriveJournalRules.clean(p)));}
 public static void main(String[] args)throws Exception{
  for(String type:OfferContract.types()){
   JSONObject s=state(),p=row(type);OfferRules.normalize(p,null,s);yes(OfferRules.validate(p,s).getBoolean("valid"));yes(p.getString("binding_mode").equals(OfferContract.type(type).getString("binding_mode")));s.getJSONArray("offers").put(p);
   OfferJournalRules.apply(s,action("offer_validate",expected(p)));p=s.getJSONArray("offers").getJSONObject(0);yes(p.getString("status").equals("validated"));
   JSONObject frozen=new JSONObject(p.toString());OfferJournalRules.apply(s,action("offer_finalize",expected(p).put("expected_context_hash",PixelMcpWriteTools.hash(OfferTools.context(p,s))).put("confirmed",true).put("pdf_sha256","a".repeat(64))));p=s.getJSONArray("offers").getJSONObject(0);yes(p.getString("status").equals("finalized"));yes(p.getString("offer_number").startsWith(type.startsWith("estimate_")?"KV-":"ANG-"));yes(s.getJSONArray("invoices").length()==0);yes(p.getString("delivery_status").equals("not_prepared"));
   JSONObject finalRow=p;bad(()->OfferRules.normalize(new JSONObject(finalRow.toString()),finalRow,s));bad(()->OfferJournalRules.apply(s,action("offer_share",expected(frozen))));
   OfferJournalRules.apply(s,action("offer_share",expected(p)));p=s.getJSONArray("offers").getJSONObject(0);yes(p.getString("delivery_status").equals("share_prepared"));yes(p.getString("status").equals("finalized"));yes(!p.has("sent_at"));JSONObject sharing=p;bad(()->OfferJournalRules.apply(s,action("offer_delivery",expected(sharing).put("confirmed",true).put("receipt",new JSONObject().put("message_id","unverified")))));
   s.getJSONObject("business_settings").put("owner_name","");s.getJSONArray("customers").getJSONObject(0).put("name","");yes(OfferRules.validate(p,s).getBoolean("valid"));
  }
  for(String type:new String[]{"estimate_binding","estimate_nonbinding"}){
   JSONObject s=state(),p=row(type).put("binding_confirmed",false);OfferRules.normalize(p,null,s);yes(!OfferRules.validate(p,s).getBoolean("valid"));yes(OfferRules.validate(p,s).getJSONObject("field_errors").has("binding_confirmed"));
   p.put("binding_confirmed",true);yes(OfferRules.validate(p,s).getBoolean("valid"));JSONObject changed=new JSONObject(p.toString()).put("document_type",type.equals("estimate_binding")?"estimate_nonbinding":"estimate_binding");OfferRules.normalize(changed,p,s);yes(!changed.getBoolean("binding_confirmed"));yes(!OfferRules.validate(changed,s).getBoolean("valid"));
  }
  JSONObject original=row("estimate_binding");OfferRules.normalize(original,null,state());JSONObject edited=new JSONObject(original.toString()).put("binding_notice","Geänderter Text");OfferRules.normalize(edited,original,state());yes(!edited.getBoolean("binding_confirmed"));
  JSONObject s=state(),p=row("fixed_price");s.getJSONObject("business_settings").put("offer_time_material_text","Regie nur nach tatsächlichem Aufwand");OfferRules.normalize(p,null,s);yes(p.getString("binding_notice").isEmpty());
  for(String source:new String[]{"Vom Nutzer bestätigt","user-confirmed","catalog","","USER_CONFIRMED"}){JSONObject invalid=row("fixed_price");invalid.getJSONArray("positions").getJSONObject(0).put("price_source",source);bad(()->OfferRules.normalize(invalid,null,state()));JSONObject input=new JSONObject().put("request_id","schema-price").put("customer_id","c").put("positions",invalid.getJSONArray("positions"));bad(()->McpSchema.validate(input,OfferTools.schema("create_offer_draft")));}
  JSONObject calc=row("estimate_binding");JSONObject line=calc.getJSONArray("positions").getJSONObject(0);line.put("price_basis","calculated").put("price_note","Freigegebener Satz × Faktor").put("calculation",new JSONObject().put("base_price",25).put("factor",2));OfferRules.normalize(calc,null,state());yes(OfferRules.validate(calc,state()).getBoolean("valid"));line.put("price",60);OfferRules.normalize(calc,null,state());yes(!OfferRules.validate(calc,state()).getBoolean("valid"));line.put("price_basis","estimated").put("price_note","");yes(!OfferRules.validate(calc,state()).getBoolean("valid"));
  JSONObject isolated=state();isolated.getJSONArray("customers").put(new JSONObject(isolated.getJSONArray("customers").getJSONObject(0).toString()).put("id","test-c").put("name","[TEST] Isolierter Kunde").put("test_record",true));
  JSONObject test=row("estimate_binding").put("test_record",true);bad(()->OfferRules.normalize(test,null,isolated));test.put("customer_id","test-c");OfferRules.normalize(test,null,isolated);yes(test.getBoolean("test_record"));bad(()->TestDataRules.noDelivery(test,isolated));test.put("billing_customer_id","c");bad(()->OfferRules.normalize(test,null,isolated));
  isolated.getJSONArray("offers").put(new JSONObject(test.toString()).put("billing_customer_id","test-c"));yes(TestDataRules.localOnly(action("archive",new JSONObject().put("entity","offer").put("id","off")),isolated));
  JSONObject real=state().getJSONArray("customers").getJSONObject(0);JSONObject changed=new JSONObject(real.toString()).put("name","[TEST] Incorrect conversion").put("test_record",true);bad(()->DriveJournalRules.validateChange("customer",changed,real,state()));
  bad(()->OfferRules.normalize(row("unknown_type"),null,state()));yes(!OfferRules.contractView(row("unknown_type")).getBoolean("supported"));
  JSONObject raw=row("fixed_price");raw.getJSONArray("positions").getJSONObject(0).put("quantity",0);bad(()->OfferRules.normalize(raw,null,state()));bad(()->McpSchema.validate(new JSONObject().put("request_id","zero").put("customer_id","c").put("positions",raw.getJSONArray("positions")),OfferTools.schema("create_offer_draft")));
  JSONObject fields=OfferTools.fields();for(String[] pair:new String[][]{{"document_type","document_types"},{"customer_type","customer_types"},{"contract_channel","contract_channels"},{"tax_mode","tax_modes"}}){JSONArray actual=fields.getJSONObject(pair[0]).getJSONArray("enum");String[] expected=pair[1].equals("document_types")?OfferContract.types():OfferContract.values(pair[1]);yes(new HashSet<>(actual.toList()).equals(new HashSet<>(Arrays.asList(expected))));}
  JSONObject lineSchema=fields.getJSONObject("positions").getJSONObject("items").getJSONObject("properties");for(String[] pair:new String[][]{{"price_source","price_sources"},{"price_basis","price_bases"}})yes(new HashSet<>(lineSchema.getJSONObject(pair[0]).getJSONArray("enum").toList()).equals(new HashSet<>(Arrays.asList(OfferContract.values(pair[1])))));for(String field:OfferContract.values("required_fields"))yes(fields.has(field));
  JSONObject oldSnapshot=state();oldSnapshot.remove("offers");JSONObject oldState=new JSONObject().put("master",oldSnapshot).put("pending",new JSONArray());yes(PixelMcpReadTools.effective(oldState).getJSONArray("offers").length()==0);JSONObject legacy=row("estimate_nonbinding");legacy.remove("binding_confirmed");String legacyHash=PixelMcpWriteTools.hash(legacy);yes(OfferRules.contractView(legacy).getBoolean("legacy_missing_binding_confirmation"));yes(PixelMcpWriteTools.hash(legacy).equals(legacyHash));
  PixelMcpWriteTools.Sink failure=new PixelMcpWriteTools.Sink(){public JSONObject execute(String n,JSONObject a)throws Exception{throw new DriveRestClient.Failure("MAIL_TEMPORARY_UNAVAILABLE","Synthetischer temporärer Fehler",12000,false);}public JSONObject status(String i,JSONObject s){return new JSONObject();}};
  PixelMcpReadTools rpc=new PixelMcpReadTools(()->PixelMcpWriteTests.state(),failure);JSONObject response=rpc.rpc(new JSONObject().put("jsonrpc","2.0").put("id",1).put("method","tools/call").put("params",new JSONObject().put("name","create_customer").put("arguments",new JSONObject().put("request_id","safe-provider-error").put("name","[TEST] Kein Speichern"))));JSONObject problem=response.getJSONObject("result").getJSONObject("structuredContent").getJSONObject("error");yes(problem.getString("code").equals("MAIL_TEMPORARY_UNAVAILABLE")&&problem.getLong("retry_after_ms")==12000);
  yes(PixelDriveState.retryableInfrastructure(new JSONObject().put("code","SYNC_COMPONENT_UPDATE_REQUIRED"),"offer_validate"));
  gmail();System.out.println("PASS "+checks+" shared estimate, price/schema, immutable status, test-isolation and real-receipt validation contracts");
 }
 static void gmail()throws Exception{
  byte[] pdf="%PDF-1.4 synthetic original".getBytes(StandardCharsets.UTF_8);String hash=DriveRestClient.sha256(pdf);JSONObject offer=new JSONObject().put("delivery_recipient","recipient@example.invalid").put("issuer",new JSONObject().put("business_email","sender@example.invalid")).put("pdf_sha256",hash);
  JSONObject msg=new JSONObject().put("id","message_1").put("internalDate","1792353600000").put("labelIds",new JSONArray().put("SENT")).put("payload",new JSONObject().put("mimeType","multipart/mixed").put("headers",new JSONArray().put(new JSONObject().put("name","To").put("value","recipient@example.invalid")).put(new JSONObject().put("name","From").put("value","Sender <sender@example.invalid>"))).put("parts",new JSONArray().put(new JSONObject().put("mimeType","application/pdf").put("body",new JSONObject().put("size",pdf.length).put("data",Base64.getUrlEncoder().encodeToString(pdf))))));
  int[] calls={0};OfferDeliveryClient client=new OfferDeliveryClient(()->"synthetic-token",(method,url,headers,body,max)->{yes(method.equals("GET")&&body==null&&url.startsWith("https://www.googleapis.com/gmail/v1/users/me/"));calls[0]++;return new DriveRestClient.Reply(200,msg.toString().getBytes(StandardCharsets.UTF_8),Collections.emptyMap());});
  yes(client.verify("message_1",offer).getString("verified_by").equals("pixel_gmail_readback"));msg.put("labelIds",new JSONArray().put("DRAFT"));bad(()->client.verify("message_1",offer));msg.put("labelIds",new JSONArray().put("SENT"));bad(()->client.verify("message_1",new JSONObject(offer.toString()).put("pdf_sha256","b".repeat(64))));bad(()->client.verify("../../invalid",offer));
  OfferDeliveryClient limited=new OfferDeliveryClient(()->"synthetic-token",(m,u,h,b,max)->new DriveRestClient.Reply(429,new byte[0],Collections.singletonMap("Retry-After","12")));try{limited.verify("message_1",offer);throw new AssertionError("429 expected");}catch(DriveRestClient.Failure e){yes(e.retryAfter==12000&&!e.userAction);}
  OfferDeliveryClient denied=new OfferDeliveryClient(()->"synthetic-token",(m,u,h,b,max)->new DriveRestClient.Reply(401,new byte[0],Collections.emptyMap()));bad(()->denied.verify("message_1",offer));yes(calls[0]==3);
 }
